css:
.print-format { padding: 10mm; }
.mr-print { direction: rtl; text-align: right; font-family: "Tajawal", "Cairo", "Arial", sans-serif; }
.mr-title { text-align: center; font-weight: bold; font-size: 17px; margin: 10px 0 25px; }
.mr-table { width: 100%; border-collapse: collapse; }
.mr-table th { background-color: #1f2621 !important; color: #fff !important; font-weight: bold; font-size: 13px; padding: 10px 6px; text-align: center; border: 1px solid #1f2621; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.mr-table td { border: 1px solid #333; padding: 12px 6px; text-align: center; font-size: 13px; vertical-align: middle; }
.mr-sign { margin-top: 120px; font-weight: bold; font-size: 14px; }
.mr-sign p { margin-bottom: 45px; }
